from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Remove spaces from the input string
    result = []  # Initialize an empty list to store the extracted groups
    stack = []  # Stack to track opening and closing parentheses

    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')' and stack:
            stack.pop()
            if not stack:  # If stack is empty, a standalone group is found
                result.append(paren_string[paren_string.index(stack[0]):paren_string.index(char)+1])

    return result

